    // Setting the state with the movie properties
    setBgImage(`https://image.tmdb.org/t/p/original${posterPath}`);
    setMovieTitle(title);
    setMovieOverview(overview);
    setReleaseDate(releaseDate);
    setSelectedMovie(results[randomIndex]);
  };

  // Defining a function to play the trailer for a movie
