      {
        params: {
          api_key: apiKey,
        },
      }
    );

    // Finding the first video with type "Trailer"
    const trailer = response.data.results.find(
      (video) => video.type === 'Trailer' && video.site === 'YouTube'
    );

    // Setting the trailer video state
    setTrailerVideo(trailer);
  };

  // Defining a function to close the trailer modal
  const closeTrailer = () => {
    setSelectedMovie(null);
    setTrailerVideo(null);
  };

  // Using an effect hook to fetch a random movie when the component mounts
  useEffect(() => {
    fetchRandomMovie();
  }, []);

  // Rendering the hero section with the hero content and buttons for adding to watchlist and playing trailer
  return (
   <div>
     <div className={styles.HeroSection} style={{ backgroundImage: `url(${bgImage})` }}>
